// ─── File: src/test/java/com/bank/cfwhen/WhenToUseCFTest.java ───
package com.bank.cfwhen;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class WhenToUseCFTest {

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }

    // ═══ CF HELPS: parallel independent IO ═══
    @Test
    void parallel_independentIO_faster() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(3);

        long start = System.currentTimeMillis();
        CompletableFuture<Integer> balance = CompletableFuture.supplyAsync(() -> { sleep(200); return 100000; }, pool);
        CompletableFuture<Integer> score = CompletableFuture.supplyAsync(() -> { sleep(200); return 750; }, pool);
        CompletableFuture<Integer> property = CompletableFuture.supplyAsync(() -> { sleep(200); return 5000000; }, pool);

        CompletableFuture.allOf(balance, score, property).get();
        long parallel = System.currentTimeMillis() - start;

        // Sequential comparison:
        long start2 = System.currentTimeMillis();
        sleep(200); sleep(200); sleep(200);
        long sequential = System.currentTimeMillis() - start2;

        System.out.println("Parallel: " + parallel + "ms, Sequential: " + sequential + "ms");
        assertThat(parallel).isLessThan(sequential);  // parallel wins!
        pool.shutdown();
    }

    // ═══ CF NO HELP: sequential dependencies ═══
    @Test
    void sequential_dependencies_noSpeedup() throws Exception {
        // CF version (still sequential!):
        long start = System.currentTimeMillis();
        String result = CompletableFuture
            .supplyAsync(() -> { sleep(100); return "SAV2001"; })
            .thenApply(id -> { sleep(100); return id + ":100000"; })
            .thenApply(data -> { sleep(100); return data + ":interest"; })
            .get();
        long cfTime = System.currentTimeMillis() - start;

        // Direct version (same speed, less overhead):
        long start2 = System.currentTimeMillis();
        sleep(100); String id = "SAV2001";
        sleep(100); String data = id + ":100000";
        sleep(100); String result2 = data + ":interest";
        long directTime = System.currentTimeMillis() - start2;

        System.out.println("CF sequential: " + cfTime + "ms, Direct: " + directTime + "ms");
        // CF is same or SLOWER (thread switch overhead)!
    }

    // ═══ CF NO HELP: supplyAsync().get() immediately ═══
    @Test
    void immediateGet_noSpeedup() throws Exception {
        long start = System.currentTimeMillis();
        String result = CompletableFuture.supplyAsync(() -> {
            sleep(200); return "data";
        }).get();  // blocks immediately!
        long cfTime = System.currentTimeMillis() - start;

        long start2 = System.currentTimeMillis();
        sleep(200); String result2 = "data";
        long directTime = System.currentTimeMillis() - start2;

        System.out.println("CF+get: " + cfTime + "ms, Direct: " + directTime + "ms");
        // Same! CF adds overhead for zero benefit!
    }
}
